using System;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
namespace LocalGame {
 public sealed class DragFollower:MonoBehaviour {
  public Vector2 Target;Vector2 velocity;bool ready;public void Set(Vector2 point){Target=point;if(!ready){((RectTransform)transform).anchoredPosition=point;ready=true;}}
  void Update(){var r=(RectTransform)transform;if(Studio.Profile?.ReducedMotion??false){r.anchoredPosition=Target;return;}r.anchoredPosition=Vector2.SmoothDamp(r.anchoredPosition,Target,ref velocity,.035f,12000,Time.unscaledDeltaTime);}
 }
 public sealed class LandingArt:MonoBehaviour {
  float age;Vector3 scale;void Awake(){scale=transform.localScale;}
  void Update(){if(Studio.Profile?.ReducedMotion??false){transform.localScale=scale;enabled=false;return;}age+=Time.unscaledDeltaTime;float t=age/.28f;float punch=Mathf.Sin(t*Mathf.PI*2.3f)*Mathf.Exp(-t*4)*.15f;transform.localScale=Vector3.Scale(scale,new Vector3(1-punch*.45f,1+punch,1));if(t>=1){transform.localScale=scale;enabled=false;}}
 }
 public sealed class FootprintPreview:MaskableGraphic {
  public Vector2Int[] Cells;public int Columns,Rows,X,Y;public bool Legal;public void Change(int x,int y,bool legal){X=x;Y=y;Legal=legal;SetVerticesDirty();}
  protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();if(Cells==null||Columns<1||Rows<1||X<0||Y<0)return;Rect r=rectTransform.rect;float cw=r.width/Columns,ch=r.height/Rows;Color c=Legal?FlatUI.Hex("#62FFD1"):FlatUI.Hex("#FF4E67");foreach(var cell in Cells){int x=X+cell.x,y=Y+cell.y;if(x<0||y<0||x>=Columns||y>=Rows)continue;float l=r.xMin+x*cw+3,t=r.yMax-y*ch-3;var b=new Rect(l,t-ch+6,cw-6,ch-6);var fill=c;fill.a=.32f;CraftedPanel.Polygon(vh,b,fill,4);CraftedPanel.Line(vh,new Vector2(b.xMin,b.yMin),new Vector2(b.xMax,b.yMin),2.6f,c);CraftedPanel.Line(vh,new Vector2(b.xMin,b.yMax),new Vector2(b.xMax,b.yMax),2.6f,c);CraftedPanel.Line(vh,new Vector2(b.xMin,b.yMin),new Vector2(b.xMin,b.yMax),2.6f,c);CraftedPanel.Line(vh,new Vector2(b.xMax,b.yMin),new Vector2(b.xMax,b.yMax),2.6f,c);}}
 }
 public sealed class ReadyGlow:MonoBehaviour {CraftedPanel frame;float time;void Start(){frame=GetComponentInChildren<CraftedPanel>();}void Update(){if(!frame)return;time+=Time.unscaledDeltaTime;frame.Heat=(Studio.Profile?.ReducedMotion??false)?.35f:.25f+.35f*(.5f+.5f*Mathf.Sin(time*3));frame.Refresh();}}
 public sealed class HudPulse:MonoBehaviour {float age=1;public void Punch(){age=0;}void Update(){if(Studio.Profile?.ReducedMotion??false){transform.localScale=Vector3.one;return;}age+=Time.unscaledDeltaTime;transform.localScale=Vector3.one*(1+.12f*Mathf.Sin(Mathf.Clamp01(age/.22f)*Mathf.PI));}}
 public sealed class ResourceToken:MaskableGraphic {public int Kind;protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;Draw(vh,r.center,Mathf.Min(r.width,r.height)*.46f,Kind);}public static void Draw(VertexHelper vh,Vector2 p,float s,int kind){Color c=FlatUI.Hex(kind==0?"#72FFD1":kind==1?"#FFD357":"#8EDBFF");CraftedPanel.Polygon(vh,new Rect(p.x-s,p.y-s,2*s,2*s),new Color(.01f,.1f,.15f,.9f),s*.4f);if(kind==0){Disc(vh,p+Vector2.up*s*.35f,s*.27f,c);CraftedPanel.Polygon(vh,new Rect(p.x-s*.58f,p.y-s*.63f,s*1.16f,s*.67f),c,s*.18f);}else if(kind==1){var box=new Rect(p.x-s*.65f,p.y-s*.65f,s*1.3f,s*1.3f);CraftedPanel.Polygon(vh,box,c,1);CraftedPanel.Line(vh,new Vector2(p.x,box.yMin),new Vector2(p.x,box.yMax),2,FlatUI.Hex("#B87527"));}else{int k=vh.currentVertCount;foreach(var q in new[]{new Vector2(.1f,1),new Vector2(-.7f,-.1f),new Vector2(.1f,-.1f),new Vector2(-.1f,-1),new Vector2(.7f,.2f),new Vector2(-.1f,.2f)})vh.AddVert(p+q*s,c,Vector2.zero);vh.AddTriangle(k,k+1,k+2);vh.AddTriangle(k+2,k+3,k+4);vh.AddTriangle(k,k+2,k+4);}}static void Disc(VertexHelper vh,Vector2 p,float r,Color c){int k=vh.currentVertCount;vh.AddVert(p,c,Vector2.zero);for(int i=0;i<=16;i++){float a=i*Mathf.PI/8;vh.AddVert(p+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*r,c,Vector2.zero);}for(int i=0;i<16;i++)vh.AddTriangle(k,k+i+1,k+i+2);}}
}
